// AUTO-GENERATED — DO NOT EDIT THIS FILE.
// Generated by scripts/build.mjs on every build. Edit the source instead, then run `npm run build`.
// The demo "preview" switch: ?advent-preview=YYYY-MM-DD pretends it is that date, on the calendar page only
// (the cross-origin teaser embed never reads a query string from the host site, so it has no preview mode).
// Pure functions. This module has no storage of any kind, so preview mode cannot remember anything.
// Anything invalid is silently ignored and never echoed back.
import { londonDateParts } from './date.js';

export const PREVIEW_PARAM = 'advent-preview';
const LAST_NOTICE_YEAR = 2100;
const FIRST_PREVIEW_YEAR = 2026;
const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

/**
 * Reads the preview date from a query string such as "?advent-preview=2026-12-07".
 * Returns {year, month, day} or null. Never throws.
 * Allowed range: 1 Nov of the season year to 31 Jan of the next year, and not before 2026.
 * A repeated parameter is treated as invalid.
 */
export function parsePreviewDate(search, realParts) {
  try {
    if (typeof search !== 'string' || !realParts) return null;
    const values = new URLSearchParams(search).getAll(PREVIEW_PARAM);
    if (values.length !== 1) return null;
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(values[0]);
    if (!match) return null;

    const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
    const asDate = new Date(Date.UTC(year, month - 1, day));
    const roundTrips =
      asDate.getUTCFullYear() === year && asDate.getUTCMonth() === month - 1 && asDate.getUTCDate() === day;
    if (!roundTrips || year < FIRST_PREVIEW_YEAR) return null;

    const seasonYear = realParts.month >= 2 ? realParts.year : realParts.year - 1;
    const earliest = Date.UTC(seasonYear, 10, 1);
    const latest = Date.UTC(seasonYear + 1, 0, 31);
    return asDate.getTime() >= earliest && asDate.getTime() <= latest ? { year, month, day } : null;
  } catch {
    return null;
  }
}

/**
 * The date the calendar page should act on. Preview is always allowed (there is no secret to protect: the
 * calendar's own season logic already keeps a visitor calm outside the season, whatever the real date is;
 * the switch exists so the church can rehearse a date before 1 December). Returns {parts, preview}; parts
 * is null if even the real date could not be worked out.
 */
export function effectiveDate({ realNow, search, timeZone = 'Europe/London' } = {}) {
  const realParts = londonDateParts(realNow, timeZone);
  const previewParts = parsePreviewDate(search, realParts);
  return previewParts ? { parts: previewParts, preview: true } : { parts: realParts, preview: false };
}

/** "Preview mode: not today's date. Showing 7 December 2026.", built from numbers only. */
export function formatPreviewNotice(parts) {
  const fallback = "Preview mode: not today's date.";
  const numbers = Boolean(parts) && [parts.year, parts.month, parts.day].every(Number.isInteger);
  if (!numbers || parts.year < FIRST_PREVIEW_YEAR || parts.year > LAST_NOTICE_YEAR || parts.month < 1 || parts.month > 12) return fallback;
  const daysInMonth = new Date(Date.UTC(parts.year, parts.month, 0)).getUTCDate();
  if (parts.day < 1 || parts.day > daysInMonth) return fallback;
  return `${fallback} Showing ${parts.day} ${MONTH_NAMES[parts.month - 1]} ${parts.year}.`;
}
